INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es hier egal, wie viel Arbeit gleichzeitig läuft?', 2, '[{"text": "Nein", "correct": true, "because": "Abgrenzung mit WIP-Limits"}, {"text": "Ja", "correct": false, "because": "Begrenzung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft mir, den Überblick zu behalten?', 3, '[{"text": "Visualisierung", "correct": true, "because": "Sichtbarkeit des Workflows"}, {"text": "Abgrenzung", "correct": false, "because": "Begrenzung der Arbeit"}, {"text": "Optimierung", "correct": false, "because": "Verbesserung des Flusses"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Grundregeln fördern einen besseren Ablauf?', 5, '[{"text": "Visualisierung", "correct": true, "because": "Transparenz schaffen"}, {"text": "Abgrenzung", "correct": true, "because": "Überlastung vermeiden"}, {"text": "Unbegrenzte Aufgaben", "correct": false, "because": "Widerspricht WIP"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) WIP-Limits begrenzen Arbeit. b) Visualisierung ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Visualisierung essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesen Prinzipien?', 4, '[{"text": "Visualisierung", "correct": false, "because": "Kern der Übersicht"}, {"text": "WIP-Limits", "correct": false, "because": "Abgrenzung zentral"}, {"text": "Unbegrenzte Arbeit", "correct": true, "because": "Begrenzung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier alles unsichtbar lassen kann?', 2, '[{"text": "Nein", "correct": true, "because": "Visualisierung ist Prinzip"}, {"text": "Ja", "correct": false, "because": "Sichtbarkeit nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich, um Überlastung zu vermeiden?', 3, '[{"text": "Abgrenzung", "correct": true, "because": "WIP-Limits setzen"}, {"text": "Visualisierung", "correct": false, "because": "Zeigt nur Status"}, {"text": "Optimierung", "correct": false, "because": "Verbessert Fluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente verbessern meinen Workflow?', 5, '[{"text": "Optimierung", "correct": true, "because": "Fluss verbessern"}, {"text": "Visualisierung", "correct": true, "because": "Status sichtbar"}, {"text": "Endlose Aufgaben", "correct": false, "because": "Widerspricht Abgrenzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Visualisierung macht Arbeit sichtbar. b) WIP-Limits sind unwichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "WIP-Limits essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Visualisierung", "correct": false, "because": "Grundprinzip"}, {"text": "Abgrenzung", "correct": false, "because": "Überlastung vermeiden"}, {"text": "Chaos ohne Limits", "correct": true, "because": "WIP-Limits nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Optimierung hier zweitrangig?', 2, '[{"text": "Nein", "correct": true, "because": "Kernprinzip"}, {"text": "Ja", "correct": false, "because": "Workflow verbessern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze sorgen für Klarheit?', 4, '[{"text": "Visualisierung", "correct": true, "because": "Status sichtbar machen"}, {"text": "Abgrenzung", "correct": true, "because": "Arbeit kontrollierbar"}, {"text": "Unbegrenzte Tasks", "correct": false, "because": "Verwirrt Workflow"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier alles gleichzeitig machen kann. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "WIP-Limits begrenzen"}, {"text": "Ja", "correct": false, "because": "Abgrenzung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem neuen Projekt?', 3, '[{"text": "Visualisierung", "correct": true, "because": "Überblick schaffen"}, {"text": "Unbegrenzte Arbeit", "correct": false, "because": "WIP-Limits nötig"}, {"text": "Keine Optimierung", "correct": false, "because": "Fluss verbessern"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Optimierung verbessert den Fluss. b) Visualisierung ist nebensächlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Visualisierung zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile haben diese Prinzipien?', 5, '[{"text": "Klarer Überblick", "correct": true, "because": "Visualisierung hilft"}, {"text": "Gesteuerter Fluss", "correct": true, "because": "Abgrenzung und Optimierung"}, {"text": "Überlastung", "correct": false, "because": "WIP-Limits verhindern"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Visualisierung", "correct": false, "because": "Kernprinzip"}, {"text": "WIP-Limits", "correct": false, "because": "Abgrenzung nötig"}, {"text": "Unkontrollierte Arbeit", "correct": true, "because": "Begrenzung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich hier ohne Sichtbarkeit arbeiten?', 3, '[{"text": "Nein", "correct": true, "because": "Visualisierung essenziell"}, {"text": "Ja", "correct": false, "because": "Sichtbarkeit zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier alles gleichzeitig bearbeiten soll?', 2, '[{"text": "Nein", "correct": true, "because": "Abgrenzung mit WIP-Limits"}, {"text": "Ja", "correct": false, "because": "Begrenzung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich für besseren Fluss?', 4, '[{"text": "Optimierung", "correct": true, "because": "Workflow verbessern"}, {"text": "Unbegrenzte Tasks", "correct": false, "because": "Widerspricht Abgrenzung"}, {"text": "Keine Sichtbarkeit", "correct": false, "because": "Visualisierung nötig"}]');
